import{_ as s,H as n,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"13 | 小数据包应对之策：理解TCP协议中的动态数据传输","description":"","frontmatter":{},"headers":[{"level":2,"title":"调用数据发送接口以后……","slug":"调用数据发送接口以后","link":"#调用数据发送接口以后","children":[]},{"level":2,"title":"流量控制和生产者-消费者模型","slug":"流量控制和生产者-消费者模型","link":"#流量控制和生产者-消费者模型","children":[]},{"level":2,"title":"拥塞控制和数据传输","slug":"拥塞控制和数据传输","link":"#拥塞控制和数据传输","children":[]},{"level":2,"title":"一些有趣的场景","slug":"一些有趣的场景","link":"#一些有趣的场景","children":[]},{"level":2,"title":"禁用Nagle算法","slug":"禁用nagle算法","link":"#禁用nagle算法","children":[]},{"level":2,"title":"将写操作合并","slug":"将写操作合并","link":"#将写操作合并","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"网络编程实战/13-小数据包应对之策：理解TCP协议中的动态数据传输.md","filePath":"网络编程实战/13-小数据包应对之策：理解TCP协议中的动态数据传输.md","lastUpdated":1779821786000}'),l={name:"网络编程实战/13-小数据包应对之策：理解TCP协议中的动态数据传输.md"};function i(t,a,o,r,c,d){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="_13-小数据包应对之策-理解tcp协议中的动态数据传输" tabindex="-1">13 | 小数据包应对之策：理解TCP协议中的动态数据传输 <a class="header-anchor" href="#_13-小数据包应对之策-理解tcp协议中的动态数据传输" aria-label="Permalink to &quot;13 | 小数据包应对之策：理解TCP协议中的动态数据传输&quot;">​</a></h1><p>你好，我是盛延敏，这里是网络编程实战第13讲，欢迎回来。</p><p>在上一篇文章里，我在应用程序中模拟了TCP Keep-Alive机制，完成TCP心跳检测，达到发现不活跃连接的目的。在这一讲里，我们将从TCP角度看待数据流的发送和接收。</p><p>如果你学过计算机网络的话，那么对于发送窗口、接收窗口、拥塞窗口等名词肯定不会陌生，它们各自解决的是什么问题，又是如何解决的？在今天的文章里，我希望能从一个更加通俗易懂的角度进行剖析。</p><h2 id="调用数据发送接口以后" tabindex="-1">调用数据发送接口以后…… <a class="header-anchor" href="#调用数据发送接口以后" aria-label="Permalink to &quot;调用数据发送接口以后……&quot;">​</a></h2><p>在前面的内容中，我们已经熟悉如何通过套接字发送数据，比如使用write或者send方法来进行数据流的发送。</p><p>我们已经知道， <strong>调用这些接口并不意味着数据被真正发送到网络上，其实，这些数据只是从应用程序中被拷贝到了系统内核的套接字缓冲区中，或者说是发送缓冲区中</strong>，等待协议栈的处理。至于这些数据是什么时候被发送出去的，对应用程序来说，是无法预知的。对这件事情真正负责的，是运行于操作系统内核的TCP协议栈实现模块。</p><h2 id="流量控制和生产者-消费者模型" tabindex="-1">流量控制和生产者-消费者模型 <a class="header-anchor" href="#流量控制和生产者-消费者模型" aria-label="Permalink to &quot;流量控制和生产者-消费者模型&quot;">​</a></h2><p>我们可以把理想中的TCP协议可以想象成一队运输货物的货车，运送的货物就是TCP数据包，这些货车将数据包从发送端运送到接收端，就这样不断周而复始。</p><p>我们仔细想一下，货物达到接收端之后，是需要卸货处理、登记入库的，接收端限于自己的处理能力和仓库规模，是不可能让这队货车以不可控的速度发货的。接收端肯定会和发送端不断地进行信息同步，比如接收端通知发送端：“后面那20车你给我等等，等我这里腾出地方你再继续发货。”</p><p>其实这就是发送窗口和接收窗口的本质，我管这个叫做“TCP的生产者-消费者”模型。</p><p>发送窗口和接收窗口是TCP连接的双方，一个作为生产者，一个作为消费者，为了达到一致协同的生产-消费速率、而产生的算法模型实现。</p><p>说白了，作为TCP发送端，也就是生产者，不能忽略TCP的接收端，也就是消费者的实际状况，不管不顾地把数据包都传送过来。如果都传送过来，消费者来不及消费，必然会丢弃；而丢弃反过来使得生产者又重传，发送更多的数据包，最后导致网络崩溃。</p><p>我想，理解了“TCP的生产者-消费者”模型，再反过来看发送窗口和接收窗口的设计目的和方式，我们就会恍然大悟了。</p><h2 id="拥塞控制和数据传输" tabindex="-1">拥塞控制和数据传输 <a class="header-anchor" href="#拥塞控制和数据传输" aria-label="Permalink to &quot;拥塞控制和数据传输&quot;">​</a></h2><p>TCP的生产者-消费者模型，只是在考虑单个连接的数据传递，但是， TCP数据包是需要经过网卡、交换机、核心路由器等一系列的网络设备的，网络设备本身的能力也是有限的，当多个连接的数据包同时在网络上传送时，势必会发生带宽争抢、数据丢失等，这样， <strong>TCP就必须考虑多个连接共享在有限的带宽上，兼顾效率和公平性的控制</strong>，这就是拥塞控制的本质。</p><p>举个形象一点的例子，有一个货车行驶在半夜三点的大路上，这样的场景是断然不需要拥塞控制的。</p><p>我们可以把网络设备形成的网络信息高速公路和生活中实际的高速公路做个对比。正是因为有多个TCP连接，形成了高速公路上的多队运送货车，高速公路上开始变得熙熙攘攘，这个时候，就需要拥塞控制的接入了。</p><p>在TCP协议中，拥塞控制是通过拥塞窗口来完成的，拥塞窗口的大小会随着网络状况实时调整。</p><p>拥塞控制常用的算法有“慢启动”，它通过一定的规则，慢慢地将网络发送数据的速率增加到一个阈值。超过这个阈值之后，慢启动就结束了，另一个叫做“拥塞避免”的算法登场。在这个阶段，TCP会不断地探测网络状况，并随之不断调整拥塞窗口的大小。</p><p>现在你可以发现，在任何一个时刻，TCP发送缓冲区的数据是否能真正发送出去， <strong>至少</strong> 取决于两个因素，一个是 <strong>当前的发送窗口大小</strong>，另一个是 <strong>拥塞窗口大小</strong>，而TCP协议中总是取两者中最小值作为判断依据。比如当前发送的字节为100，发送窗口的大小是200，拥塞窗口的大小是80，那么取200和80中的最小值，就是80，当前发送的字节数显然是大于拥塞窗口的，结论就是不能发送出去。</p><p>这里千万要分清楚发送窗口和拥塞窗口的区别。</p><p>发送窗口反应了作为单TCP连接、点对点之间的流量控制模型，它是需要和接收端一起共同协调来调整大小的；而拥塞窗口则是反应了作为多个TCP连接共享带宽的拥塞控制模型，它是发送端独立地根据网络状况来动态调整的。</p><h2 id="一些有趣的场景" tabindex="-1">一些有趣的场景 <a class="header-anchor" href="#一些有趣的场景" aria-label="Permalink to &quot;一些有趣的场景&quot;">​</a></h2><p>注意我在前面的表述中，提到了在任何一个时刻里，TCP发送缓冲区的数据是否能真正发送出去，用了“至少两个因素”这个说法，细心的你有没有想过这个问题，除了之前引入的发送窗口、拥塞窗口之外，还有什么其他因素吗？</p><p>我们考虑以下几个有趣的场景：</p><p>第一个场景，接收端处理得急不可待，比如刚刚读入了100个字节，就告诉发送端：“喂，我已经读走100个字节了，你继续发”，在这种情况下，你觉得发送端应该怎么做呢？</p><p>第二个场景是所谓的“交互式”场景，比如我们使用telnet登录到一台服务器上，或者使用SSH和远程的服务器交互，这种情况下，我们在屏幕上敲打了一个命令，等待服务器返回结果，这个过程需要不断和服务器端进行数据传输。这里最大的问题是，每次传输的数据可能都非常小，比如敲打的命令“pwd”，仅仅三个字符。这意味着什么？这就好比，每次叫了一辆大货车，只送了一个小水壶。在这种情况下，你又觉得发送端该怎么做才合理呢？</p><p>第三个场景是从接收端来说的。我们知道，接收端需要对每个接收到的TCP分组进行确认，也就是发送ACK报文，但是ACK报文本身是不带数据的分段，如果一直这样发送大量的ACK报文，就会消耗大量的带宽。之所以会这样，是因为TCP报文、IP报文固有的消息头是不可或缺的，比如两端的地址、端口号、时间戳、序列号等信息， 在这种情形下，你觉得合理的做法是什么？</p><p>TCP之所以复杂，就是因为TCP需要考虑的因素较多。像以上这几个场景，都是TCP需要考虑的情况，一句话概况就是如何有效地利用网络带宽。</p><p>第一个场景也被叫做糊涂窗口综合症，这个场景需要在接收端进行优化。也就是说，接收端不能在接收缓冲区空出一个很小的部分之后，就急吼吼地向发送端发送窗口更新通知，而是需要在自己的缓冲区大到一个合理的值之后，再向发送端发送窗口更新通知。这个合理的值，由对应的RFC规范定义。</p><p>第二个场景需要在发送端进行优化。这个优化的算法叫做Nagle算法，Nagle算法的本质其实就是限制大批量的小数据包同时发送，为此，它提出，在任何一个时刻，未被确认的小数据包不能超过一个。这里的小数据包，指的是长度小于最大报文段长度MSS的TCP分组。这样，发送端就可以把接下来连续的几个小数据包存储起来，等待接收到前一个小数据包的ACK分组之后，再将数据一次性发送出去。</p><p>第三个场景，也是需要在接收端进行优化，这个优化的算法叫做延时ACK。延时ACK在收到数据后并不马上回复，而是累计需要发送的ACK报文，等到有数据需要发送给对端时，将累计的ACK <strong>捎带一并发送出去</strong>。当然，延时ACK机制，不能无限地延时下去，否则发送端误认为数据包没有发送成功，引起重传，反而会占用额外的网络带宽。</p><h2 id="禁用nagle算法" tabindex="-1">禁用Nagle算法 <a class="header-anchor" href="#禁用nagle算法" aria-label="Permalink to &quot;禁用Nagle算法&quot;">​</a></h2><p>有没有发现一个很奇怪的组合，即Nagle算法和延时ACK的组合。</p><p>这个组合为什么奇怪呢？我举一个例子你来体会一下。</p><p>比如，客户端分两次将一个请求发送出去，由于请求的第一部分的报文未被确认，Nagle算法开始起作用；同时延时ACK在服务器端起作用，假设延时时间为200ms，服务器等待200ms后，对请求的第一部分进行确认；接下来客户端收到了确认后，Nagle算法解除请求第二部分的阻止，让第二部分得以发送出去，服务器端在收到之后，进行处理应答，同时将第二部分的确认捎带发送出去。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/128609/42073ad07805783add96ee87aeee8aeb.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/128609/42073ad07805783add96ee87aeee8aeb.png" alt=""></a></p><p>你从这张图中可以看到，Nagle算法和延时确认组合在一起，增大了处理时延，实际上，两个优化彼此在阻止对方。</p><p>从上面的例子可以看到，在有些情况下Nagle算法并不适用， 比如对时延敏感的应用。</p><p>幸运的是，我们可以通过对套接字的修改来关闭Nagle算法。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int on = 1;</span></span>
<span class="line"><span>setsockopt(sock, IPPROTO_TCP, TCP_NODELAY, (void *)&amp;on, sizeof(on));</span></span></code></pre></div><p>值得注意的是，除非我们对此有十足的把握，否则不要轻易改变默认的TCP Nagle算法。因为在现代操作系统中，针对Nagle算法和延时ACK的优化已经非常成熟了，有可能在禁用Nagle算法之后，性能问题反而更加严重。</p><h2 id="将写操作合并" tabindex="-1">将写操作合并 <a class="header-anchor" href="#将写操作合并" aria-label="Permalink to &quot;将写操作合并&quot;">​</a></h2><p>其实前面的例子里，如果我们能将一个请求一次性发送过去，而不是分开两部分独立发送，结果会好很多。所以，在写数据之前，将数据合并到缓冲区，批量发送出去，这是一个比较好的做法。不过，有时候数据会存储在两个不同的缓存中，对此，我们可以使用如下的方法来进行数据的读写操作，从而避免Nagle算法引发的副作用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ssize_t writev(int filedes, const struct iovec *iov, int iovcnt)</span></span>
<span class="line"><span>ssize_t readv(int filedes, const struct iovec *iov, int iovcnt);</span></span></code></pre></div><p>这两个函数的第二个参数都是指向某个iovec结构数组的一个指针，其中iovec结构定义如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct iovec {</span></span>
<span class="line"><span>void *iov_base; /* starting address of buffer */</span></span>
<span class="line"><span>size_t　iov_len; /* size of buffer */</span></span>
<span class="line"><span>};”</span></span></code></pre></div><p>下面的程序展示了集中写的方式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int main(int argc, char **argv) {</span></span>
<span class="line"><span>    if (argc != 2) {</span></span>
<span class="line"><span>        error(1, 0, &quot;usage: tcpclient &amp;lt;IPaddress&amp;gt;&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    int socket_fd;</span></span>
<span class="line"><span>    socket_fd = socket(AF_INET, SOCK_STREAM, 0);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    struct sockaddr_in server_addr;</span></span>
<span class="line"><span>    bzero(&amp;server_addr, sizeof(server_addr));</span></span>
<span class="line"><span>    server_addr.sin_family = AF_INET;</span></span>
<span class="line"><span>    server_addr.sin_port = htons(SERV_PORT);</span></span>
<span class="line"><span>    inet_pton(AF_INET, argv[1], &amp;server_addr.sin_addr);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    socklen_t server_len = sizeof(server_addr);</span></span>
<span class="line"><span>    int connect_rt = connect(socket_fd, (struct sockaddr *) &amp;server_addr, server_len);</span></span>
<span class="line"><span>    if (connect_rt &amp;lt; 0) {</span></span>
<span class="line"><span>        error(1, errno, &quot;connect failed &quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    char buf[128];</span></span>
<span class="line"><span>    struct iovec iov[2];</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    char *send_one = &quot;hello,&quot;;</span></span>
<span class="line"><span>    iov[0].iov_base = send_one;</span></span>
<span class="line"><span>    iov[0].iov_len = strlen(send_one);</span></span>
<span class="line"><span>    iov[1].iov_base = buf;</span></span>
<span class="line"><span>    while (fgets(buf, sizeof(buf), stdin) != NULL) {</span></span>
<span class="line"><span>        iov[1].iov_len = strlen(buf);</span></span>
<span class="line"><span>        int n = htonl(iov[1].iov_len);</span></span>
<span class="line"><span>        if (writev(socket_fd, iov, 2) &amp;lt; 0)</span></span>
<span class="line"><span>            error(1, errno, &quot;writev failure&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    exit(0);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这个程序的前半部分创建套接字，建立连接就不再赘述了。关键的是24-33行，使用了iovec数组，分别写入了两个不同的字符串，一个是“hello,”，另一个通过标准输入读入。</p><p>在启动该程序之前，我们需要启动服务器端程序，在客户端依次输入“world”和“network”：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>world</span></span>
<span class="line"><span>network</span></span></code></pre></div><p>接下来我们可以看到服务器端接收到了iovec组成的新的字符串。这里的原理其实就是在调用writev操作时，会自动把几个数组的输入合并成一个有序的字节流，然后发送给对端。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>received 12 bytes: hello,world</span></span>
<span class="line"><span></span></span>
<span class="line"><span>received 14 bytes: hello,network</span></span></code></pre></div><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>今天的内容我重点讲述了TCP流量控制的生产者-消费者模型，你需要记住以下几点：</p><ul><li>发送窗口用来控制发送和接收端的流量；阻塞窗口用来控制多条连接公平使用的有限带宽。</li><li>小数据包加剧了网络带宽的浪费，为了解决这个问题，引入了如Nagle算法、延时ACK等机制。</li><li>在程序设计层面，不要多次频繁地发送小报文，如果有，可以使用writev批量发送。</li></ul><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>和往常一样，留两道思考题：</p><p>针对最后呈现的writev函数，你可以查一查Linux下一次性最多允许数组的大小是多少？</p><p>另外TCP拥塞控制算法是一个非常重要的研究领域，请你查阅下最新的有关这方面的研究，看看有没有新的发现？</p><p>欢迎你在评论区写下你的思考，也欢迎把这篇文章分享给你的朋友或者同事，一起来交流。</p>`,63)])])}const u=s(l,[["render",i]]);export{g as __pageData,u as default};
